import sys


def main():
    groups = {}
    for word in sys.stdin.read().split():
        word = ''.join(char for char in word if char.isalpha()).lower()
        if word:
            sorted_word = "".join(sorted(word))
            groups.setdefault(sorted_word, []).append(word)

    group_list = []
    for key in groups:
        words = sorted(groups[key])
        if len(words) > 1:
            group_list.append((len(words), words[0], words))

    group_list.sort(key=lambda x: (-x[0], x[1]))

    for size, first_word, words in group_list:
        print(" ".join(words))


if __name__ == "__main__":
    main()
